#!/usr/bin/env bash
# lane.sh <claude-haiku-5-5|claude-sonnet-5-5|claude-opus-5-5> <low|medium|high>
# One lane = one model x one effort; 6 roles serial: reviewer owner brain verification_author consult discuss.
# DRAFT. Never calls engine-scorecard.js record. DRY_RUN=1 prints the commands only (no staging, no spend).
# Real run: setsid nohup bash lane.sh <model> <effort> > out/<lane>.log 2>&1 < /dev/null & disown ; Monitor for 'rc='
# (harness memory guard kills >5min run_in_background jobs; do not edit this file while it runs).
set -uo pipefail
MODEL="${1:?model}"; EFFORT="${2:?effort}"
case "$MODEL" in claude-haiku-5-5|claude-sonnet-5-5|claude-opus-5-5) ;; *) echo "bad model" >&2; exit 2;; esac
case "$EFFORT" in low|medium|high) ;; *) echo "bad effort" >&2; exit 2;; esac
SHORT="${MODEL#claude-}"; SHORT="${SHORT%-5-5}"; LANE="$SHORT-$EFFORT"
HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO="${REPO_OVERRIDE:-/home/cookys/projects/autopilot/.claude/worktrees/agent-a16d390b66014e3cf}"
DRY="${DRY_RUN:-0}"
LANE_DIR="$HOME/.autopilot/exam-claude-config-$LANE"
OUT="$HERE/out/rv6-claude-$LANE"
ROLES=(${ROLES_OVERRIDE:-reviewer owner brain verification_author consult discuss})
say() { echo "$(date -Is) $*"; }

cd "$REPO" || exit 2
if [ "$DRY" != 1 ]; then
  free -g | sed -n 2p
  # dedicated per-lane config dir: credentials only (NEVER real ~/.claude as CLAUDE_CONFIG_DIR)
  source "$REPO/scripts/lib/qualify-stage-credentials.sh"
  mkdir -p "$LANE_DIR" && chmod 700 "$LANE_DIR"
  qualify_stage_credential "$LANE_DIR/.credentials.json" "$HOME/.claude/.credentials.json" execute
  [ -f "$LANE_DIR/.credentials.json" ] || { echo "no credentials staged" >&2; echo "rc=2"; exit 2; }
fi
node "$HERE/claude-derive.js" "$MODEL" "$EFFORT" "$REPO" > /dev/null || { echo "fingerprint derivation failed"; echo "rc=2"; exit 2; }
idv() { node -e "console.log(require('$HERE/identity/$1-$LANE.json')['$2'])"; }

# role -> prompt mode / provider cmd / task class / extra flags
run_role() {
  local role="$1" d="$OUT/$1" mode cmd tc extra=() emit=1
  mkdir -p "$d/raw"
  cmd="node $REPO/scripts/qualification-review-provider.js"
  case "$role" in
    reviewer)            mode=reviewer; tc=code_review;;
    owner)               mode=owner;    tc=owner_intent_control; cmd="node $HERE/owner-provider.js";;  # no repo provider mode
    brain)               mode=brain;    tc=brain-seat; emit=0;;                                      # brain: no row, no record
    verification_author) mode=va;       tc=verification_authoring;;
    consult)             mode=consult;  tc=consult;  extra=(--execute);;                              # pools up to 3 administrations internally
    discuss)             mode=discuss;  tc=discuss;  extra=(--execute);;
  esac
  [ "$emit" = 1 ] && extra+=(--emit-row)
  local tmo; case "$role" in consult|discuss) tmo=21600;; reviewer) tmo=18000;; *) tmo=10800;; esac
  local ARGV=(timeout "$tmo" bash "$REPO/scripts/engine-qualify.sh" "$role"
    --engine "$MODEL" --model "$MODEL" --model-version "$MODEL"
    --runner claude-native --runner-version "$(idv "$role" runner_version)" --family anthropic
    --harness-version "$(idv "$role" harness_version)" --effort "$EFFORT"
    --prompt-config-hash "$(idv "$role" prompt_config_hash)"
    --semantic-fingerprint "$(idv "$role" semantic_fingerprint)"
    --containment-fingerprint "$(idv "$role" containment_fingerprint)"
    --remote-provider-cmd "$cmd" --remote-provider anthropic
    --remote-timeout-ms 600000
    --provider-env QRP_MODEL --provider-env QRP_PROVIDER --provider-env QRP_PROMPT_MODE
    --provider-env QRP_TRANSPORT --provider-env QRP_CLI_KIND --provider-env QRP_CLI_EFFORT
    --provider-env QRP_TIMEOUT_MS --provider-env CLAUDE_CONFIG_DIR
    --task-class "$tc" --domain cross-cutting --language en --tool read_only
    --version-source operator-asserted
    --raw-dir "$d/raw" "${extra[@]}")
  if [ "$DRY" = 1 ]; then
    echo "[$role] QRP_TIMEOUT_MS=570000 QRP_TRANSPORT=cli QRP_CLI_KIND=claude QRP_PROMPT_MODE=$mode QRP_MODEL=$MODEL QRP_PROVIDER=anthropic QRP_CLI_EFFORT=$EFFORT CLAUDE_CONFIG_DIR=$LANE_DIR"
    printf '   %q' "${ARGV[@]}"; echo; return 0
  fi
  say "role=$role START"
  # QRP_TIMEOUT_MS (inner, 570s) < --remote-timeout-ms (outer broker, 600s cap)
  ( export QRP_TIMEOUT_MS=570000 QRP_TRANSPORT=cli QRP_CLI_KIND=claude QRP_PROMPT_MODE="$mode" \
      QRP_MODEL="$MODEL" QRP_PROVIDER=anthropic QRP_CLI_EFFORT="$EFFORT" CLAUDE_CONFIG_DIR="$LANE_DIR"
    "${ARGV[@]}" > "$d/stdout.json" 2> "$d/stderr.log" )
  local rc=$?
  [ "$emit" = 1 ] && cp "$d/stdout.json" "$d/emit-row.json"      # row for a LATER manual `engine-scorecard.js record --file`
  # transcripts claude wrote in the lane dir (sessions); keep per role, then clear for the next role
  if [ -d "$LANE_DIR/projects" ]; then rm -rf "$d/claude-projects"; mv "$LANE_DIR/projects" "$d/claude-projects"; fi
  echo "$rc" > "$d/rc"
  say "role=$role END rc=$rc (0=pass 1=fail-verdict 2=usage/precondition 124=wall timeout)"
  return $rc
}

BAD=0; SUMMARY=""
for r in "${ROLES[@]}"; do
  run_role "$r"; rc=$?
  SUMMARY+=" $r=$rc"
  { [ "$rc" -ge 2 ] || [ "$rc" -eq 124 ]; } && BAD=$((BAD+1))
done
say "lane=$LANE summary:$SUMMARY"
if [ "$BAD" -gt 0 ]; then RC=2; else RC=0; fi   # 1 (FAIL verdict) is a result, not a lane error
echo "rc=$RC"
exit $RC
